import { test, expect } from '@playwright/test';

test.describe('Countdown Timer', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000'); // Replace with your application's URL
  });

  test('should display the initial countdown value', async ({ page }) => {
    const countdownValue = await page.getByRole('timer').innerText();
    expect(countdownValue).toBe('60'); // Assuming the countdown starts at 60 seconds
  });

  test('should update the countdown value every second', async ({ page }) => {
    const countdownElement = page.getByRole('timer');
    const initialValue = await countdownElement.innerText();

    await page.waitForTimeout(1000); // Wait for 1 second
    const updatedValue = await countdownElement.innerText();

    expect(updatedValue).not.toBe(initialValue); // Ensure the value has changed
    expect(parseInt(updatedValue)).toBe(parseInt(initialValue) - 1); // Check if it decremented by 1
  });
});
